                continue
            for dx in range(1, w):
                missing = []
                valid = True
                for k in range(2):
                    row_missing = []
                    for c in range(dx, w):
                        expected = grid[sr + k][c - dx]
                        actual = grid[tr + k][c]
                        if expected == color and actual == 0:
                            row_missing.append(c)
